const P = Number(loanPrincipal) || 0;
const r = (Number(annualRatePct) || 0) / 100 / 12;
const n = (Number(loanYears) || 1) * 12;
const paid = Number(monthsPaid) || 0;
const monthly = r > 0 ? (P * r) / (1 - Math.pow(1 + r, -n)) : P / n;
const totalPaid = monthly * n;
const totalInterest = totalPaid - P;
const interestRatio = P > 0 ? (totalInterest / P) * 100 : 0;
const balance = r > 0 ? (P * Math.pow(1 + r, paid) - monthly * (Math.pow(1 + r, paid) - 1) / r) : P - monthly * paid;
return { interestRatio, monthly, totalInterest, balance: Math.max(0, balance) };

